 "content": "def transform(grid):
    """Copy the colored motif anchored at one 5 onto the other 5 marker."""
    out = [row[:] for row in grid]
    anchors = [(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == 5]
    if len(anchors) < 2:
