    # The motif's anchor is the 5 surrounded by the denser pattern; the other
    # 5 is the isolated placement marker.
    def neighborhood_score(pos):
        r0, c0 = pos
        return sum(
            1
            for r, row in enumerate(grid)
            for c, value in enumerate(row)
            if value != 0 and (r, c) != pos and max(abs(r - r0), abs(c - c0)) <= 3
        )

    source = max(anchors, key=neighborhood_score)
    target = min((p for p in anchors if p != source), key=neighborhood_score)
    dr, dc = target[0] - source[0], target[1] - source[1]
    out[target[0]][target[1]] = 0

    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value == 0 or (r, c) in (source, target):
                continue
            rr, cc = r + dr, c + dc
            if 0 <= rr < len(out) and 0 <= cc < len(out[rr]):
                out[rr][cc] = value
    return out


